package main
import ("fmt";"os";"path/filepath";"regexp";"sort";"strconv";"strings";_"github.com/paullepoulpe/jsgo/legacy/internal/diag";"github.com/paullepoulpe/jsgo/legacy/internal/jscomp")
type t struct{l,c int;k string}
var r=regexp.MustCompile(`^(.+?):(\d+):(\d+): (?:ERROR|WARNING) - \[([A-Z_]+)\]`)
func p(s string)[]t{var o []t;for _,l:=range strings.Split(s,"\n"){m:=r.FindStringSubmatch(l);if m!=nil{ln,_:=strconv.Atoi(m[2]);cl,_:=strconv.Atoi(m[3]);o=append(o,t{ln,cl,m[4]})}};sort.Slice(o,func(i,j int)bool{if o[i].l!=o[j].l{return o[i].l<o[j].l};if o[i].c!=o[j].c{return o[i].c<o[j].c};return o[i].k<o[j].k});return o}
func run(f string)[]t{b,_:=os.ReadFile(f);d,_:=jscomp.CheckSource(f,string(b));var o []t;for _,x:=range d{o=append(o,t{x.Line,x.Col,x.Code})};sort.Slice(o,func(i,j int)bool{if o[i].l!=o[j].l{return o[i].l<o[j].l};if o[i].c!=o[j].c{return o[i].c<o[j].c};return o[i].k<o[j].k});return o}
func cs(ts []t)[]string{s:=map[string]bool{};for _,x:=range ts{s[x.k]=true};var o []string;for c:=range s{o=append(o,c)};sort.Strings(o);return o}
func main(){m,flt:="b","";if len(os.Args)>=2{m=os.Args[1]};if len(os.Args)>=3{flt=os.Args[2]};var fs []string;filepath.Walk("testdata/fixtures/extracted",func(p string,i os.FileInfo,_ error)error{if !i.IsDir()&&strings.HasSuffix(p,".js"){fs=append(fs,p)};return nil});sort.Strings(fs);b:=map[string]int{};s:=map[string][]string{};pp,f:=0,0;for _,fx:=range fs{o:="testdata/oracle"+strings.TrimSuffix(fx[len("testdata/fixtures"):],".js")+".txt";bb,e:=os.ReadFile(o);if e!=nil{continue};w:=p(string(bb));g:=run(fx);ok:=len(w)==len(g);if ok{for i:=range w{if w[i]!=g[i]{ok=false;break}}};if ok{pp++;continue};f++;k:=fmt.Sprintf("want=%v got=%v",cs(w),cs(g));if m=="l"&&flt!=""&&k==flt{fmt.Println(fx)};b[k]++;if len(s[k])<3{s[k]=append(s[k],fx)}};if m=="s"{fmt.Printf("pass=%d fail=%d rate=%.2f%%\n",pp,f,100*float64(pp)/float64(pp+f));return};type kv struct{K string;V int};var sr []kv;for k,v:=range b{sr=append(sr,kv{k,v})};sort.Slice(sr,func(i,j int)bool{return sr[i].V>sr[j].V});for _,x:=range sr{fmt.Printf("%4d %s\n",x.V,x.K);for _,e:=range s[x.K]{fmt.Printf("     %s\n",e)}};fmt.Printf("TOTAL p=%d f=%d\n",pp,f)}
